#[cfg(test)]mod resurrection61_render_development_tests {
 use super::*;
 #[test]
 #[ignore="LITO_SHARED_RESOURCE_ROOT; original3944 eight banks/1362 and230/124; memory fragments/history only"]
 fn original_cast_and_success_visuals_survive_authoritative_new_life_without_hp_prediction(){let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}let own=w.own_actor().unwrap().clone();w.actors.get_mut(&own.id).unwrap().heading=6;for gfx in [3944u16,230]{let mut b=vec![0x37];b.extend(own.id.to_le_bytes());b.extend(gfx.to_le_bytes());w.accept(&b).unwrap();}let mut b=vec![0x11];b.extend(own.id.to_le_bytes());b.push(0);b.extend(2_u32.to_le_bytes());b.extend(own.graphics.to_le_bytes());w.accept(&b).unwrap();let hp=w.hp;let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.additional_error.is_none());assert_eq!(e.additional_bank.as_ref().unwrap().sources().filter(|s|s.name.starts_with("3944-")).count(),8);let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut fragments=vec![];let(receipt,audio)=e.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,0);assert_eq!(fragments.len(),2);assert_eq!(audio.iter().filter(|a|a.sound==Some(124)&&a.actor==0&&a.prepared_audio.is_some()).count(),1);assert_eq!(receipt["effects"].as_array().unwrap().iter().find(|e|e["graphics"]==3944).unwrap()["heading"],6);drop(fragments);let h=e.history();w.actors.clear();w.effects.clear();w.finite_effect_headings.clear();let mut restored=Effects::default();restored.restore_history(h);restored.prepare(&root,&w,&cancel);let mut fragments=vec![];let(_,audio)=restored.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,125_000_000);assert_eq!(audio.iter().filter(|a|a.sound==Some(1362)&&a.actor==0&&a.prepared_audio.is_some()).count(),1);drop(fragments);assert_eq!(restored.started,2);assert_eq!(w.hp,hp);}
}
